namespace
{
    size_t checks{};
    void require(bool value, const char* message)
    {
        ++checks;
        if (!value)
        {
            throw std::runtime_error(message);
        }
    }
    thread_local size_t workerIndex{};
    std::array<std::atomic<size_t>, 17> workerBytes{}, workerRanges{};
    std::atomic<size_t> activeBuilds{}, contextErrors{};
    std::atomic<bool> failNext{}, blockBuilds{};
    bool observe = true, verifyContext{};
    void reset_observer()
    {
        for (auto& value : workerBytes)
        {
            value = 0;
        }
        for (auto& value : workerRanges)
        {
            value = 0;
        }
        contextErrors = 0;
        failNext = false;
        blockBuilds = false;
    }
    struct BuildObservation
    {
        BuildObservation()
        {
            if (!observe)
            {
                return;
            }
            ++activeBuilds;
            while (blockBuilds.load(std::memory_order_acquire))
            {
                std::this_thread::yield();
            }
            if (failNext.exchange(false))
            {
                --activeBuilds;
                throw std::runtime_error("injected materialization failure");
            }
            if (verifyContext && ce::current_cpu_context.frame != 73)
            {
                ++contextErrors;
            }
        }
        ~BuildObservation()
        {
            if (observe)
            {
                --activeBuilds;
            }
        }
    };
} // namespace

