#include "PacketProduction.inl"

namespace
{
    template<class Graph>
    struct Scene
    {
        struct Input
        {
            std::string name;
            std::vector<typename Graph::RepeatedPhase> phases;
            std::vector<typename Graph::RepeatedPhaseView> views;
        };
        Graph graph;
        std::deque<Input> inputs;
        std::deque<std::string> resourceNames;
        std::vector<std::pair<size_t, size_t>> ends;
        bool warmedNames{};

        Scene(size_t nodes, size_t passesPerNode, size_t usages, bool skew, bool resources = true)
        {
            graph.m_declarationWork = std::make_unique<typename Graph::DeclarationWork>();
            graph.resourceStorage.resize(resources ? nodes * 2 : 0);
            graph.passStorage.resize(nodes * passesPerNode);
            graph.m_resourceDeclarations.resize(graph.resourceStorage.size());
            graph.m_passDeclarations.resize(graph.passStorage.size());
            graph.m_declarationPackets.reserve(nodes);
            for (size_t node = 0; node < nodes; ++node)
            {
                if (resources)
                {
                    for (size_t r = node * 2; r < node * 2 + 2; ++r)
                    {
                        resourceNames.push_back("resource-name-" + std::to_string(r));
                        const auto& name = resourceNames.back();
                        graph.m_resourceDeclarations[r] = {name, name};
                        graph.resourceStorage[r].imported = r % 3 == 0;
                        graph.resourceStorage[r].bufferKind = r % 2 == 0;
                    }
                }
                for (size_t pass = node * passesPerNode; pass < (node + 1) * passesPerNode; ++pass)
                {
                    auto& input = inputs.emplace_back();
                    input.name = "pass-name-" + std::to_string(pass);
                    const size_t count = skew && node % 4 != 0 ? usages / 32 : usages;
                    if (count)
                    {
                        input.phases.resize(pass % 3 + 1);
                        for (size_t phase = 0; phase < input.phases.size(); ++phase)
                        {
                            auto& data = input.phases[phase];
                            data.name = "phase-name-" + std::to_string(pass) + "." + std::to_string(phase);
                            data.usages.resize(count);
                            for (size_t index = 0; index < count; ++index)
                            {
                                data.usages[index] = {pass, phase, index};
                            }
                            input.views.push_back({data.name, data.usages});
                        }
                    }
                    graph.m_passDeclarations[pass] = {input.name, input.views};
                }
                ends.emplace_back(resources ? (node + 1) * 2 : 0, (node + 1) * passesPerNode);
            }
        }
        ~Scene() { graph.CancelDeclarationPackets(); }
        void prepare(bool warmNames = false)
        {
            graph.JoinDeclarationPackets();
            graph.m_resources = {};
            graph.m_passes = {};
            graph.m_cancelledDeclarationPackets = false;
            for (size_t index = 0; index < graph.resourceStorage.size(); ++index)
            {
                auto& resource = graph.resourceStorage[index];
                resource.visits = 0;
                graph.m_resourceDeclarations[index].name =
                    warmNames ? std::string_view{resource.name} : std::string_view{resourceNames[index]};
            }
            for (size_t index = 0; index < graph.passStorage.size(); ++index)
            {
                auto& pass = graph.passStorage[index];
                pass.visits = 0;
                pass.phases = {};
                graph.m_passDeclarations[index].name =
                    warmNames ? std::string_view{pass.name} : std::string_view{inputs[index].name};
            }
            warmedNames = warmNames;
        }
        void publish(bool finish = true)
        {
            graph.BeginDeclarationPackets();
            for (const auto& [resources, passes] : ends)
            {
                graph.m_resources = std::span{graph.resourceStorage}.first(resources);
                graph.m_passes = std::span{graph.passStorage}.first(passes);
                graph.NextDeclarationPacket();
            }
            if (finish)
            {
                graph.FinishDeclarationPackets();
            }
        }
        void check()
        {
            require(!graph.m_collectingDeclarationPackets && !graph.m_cancelledDeclarationPackets,
                    "finish did not leave a usable graph");
            require(graph.m_declarationWork->pendingCount == 0, "finish retained a pending handle");
            require(graph.m_declarationWork->nextPacket == ends.size(), "not all packets were consumed");
            for (size_t index = 0; index < graph.resourceStorage.size(); ++index)
            {
                const auto& resource = graph.resourceStorage[index];
                require(resource.name == resourceNames[index], "resource name changed");
                if (!resource.imported)
                {
                    require((resource.IsBuffer() ? resource.bufferDesc.name : resource.desc.name) ==
                                resourceNames[index],
                            "resource descriptor name changed");
                }
            }
            for (size_t index = 0; index < graph.passStorage.size(); ++index)
            {
                const auto& pass = graph.passStorage[index];
                const auto& input = inputs[index];
                require(pass.name == input.name, "pass name changed");
                require(pass.phases.size() == input.phases.size(), "active phase count changed");
                for (size_t phase = 0; phase < input.phases.size(); ++phase)
                {
                    require(pass.phases[phase].name == input.phases[phase].name, "phase name changed");
                    require(pass.phases[phase].usages == input.phases[phase].usages, "phase usages changed");
                }
            }
        }
    };

    template<class Graph>
    void check_cases(size_t workers, bool current)
    {
        verifyContext = current;
        for (const size_t nodes : {size_t{0}, size_t{1}, size_t{7}, size_t{8}, size_t{9}, size_t{17}, size_t{73}})
        {
            for (const size_t usages : {size_t{0}, size_t{8}, size_t{16384}})
            {
                reset_observer();
                Scene<Graph> scene(nodes, 5, usages, true);
                scene.prepare();
                scene.publish();
                scene.check();
                require(contextErrors == 0, "worker lost the declaration profiler context");
                require(activeBuilds == 0, "finish returned before materialization completed");
                scene.prepare(true);
                reset_observer();
                scene.publish();
                scene.check();
                if (current && usages == 0)
                {
                    require(scene.graph.m_declarationPacketJobs == 0, "warm no-op submitted materialization");
                    require(scene.graph.m_packetArena.stats().used_bytes == 0, "warm no-op allocated a batch");
                }
            }
        }
        Scene<Graph> distributed(8, 16, 8192, true);
        distributed.prepare();
        distributed.publish();
        distributed.check();
        if (current)
        {
            require(distributed.graph.m_declarationPacketJobs == workers, "large useful work did not use the pool");
        }

        Scene<Graph> resourceOnly(8, 0, 0, false);
        for (size_t index = 0; index < resourceOnly.resourceNames.size(); ++index)
        {
            auto& name = resourceOnly.resourceNames[index];
            name.resize(512 * 1024, static_cast<char>('a' + index));
            resourceOnly.graph.m_resourceDeclarations[index] = {name, name};
        }
        resourceOnly.prepare();
        resourceOnly.publish();
        resourceOnly.check();
        if (current)
        {
            require(resourceOnly.graph.m_declarationPacketJobs == workers, "resource-only work lost parallel ranges");
        }

        Scene<Graph> single(1, 1, 524288, false, false);
        single.prepare();
        single.publish();
        single.check();
        if (current)
        {
            require(single.graph.m_declarationPacketJobs == 1, "a single pass was split across workers");
        }

        Scene<Graph> nested(8, 4, 8192, false);
        nested.prepare();
        ce::get_job_scheduler()
            .submit(
                [&]
                {
                    ce::profile_context_scope context{{73}};
                    nested.publish();
                })
            .wait();
        nested.check();
        require(nested.graph.m_declarationPacketJobs == 1, "nested declaration did not execute inline");

        Scene<Graph> failed(17, 8, 4096, false);
        failed.prepare();
        failNext = true;
        bool caught{};
        try
        {
            failed.publish();
        }
        catch (const std::runtime_error& error)
        {
            caught = std::string_view(error.what()) == "injected materialization failure";
            failed.graph.CancelDeclarationPackets();
        }
        require(caught && activeBuilds == 0, "worker failure did not drain before propagation");
        require(failed.graph.m_cancelledDeclarationPackets && failed.graph.m_declarationWork->pendingCount == 0,
                "failed graph was not cancelled");
        caught = false;
        try
        {
            failed.graph.BeginDeclarationPackets();
        }
        catch (const std::logic_error&)
        {
            caught = true;
        }
        require(caught, "cancelled graph was reusable without Reset");

        Scene<Graph> cancelled(8, 8, 8192, false);
        cancelled.prepare();
        cancelled.publish(false);
        cancelled.graph.CancelDeclarationPackets();
        require(activeBuilds == 0 && cancelled.graph.m_declarationWork->pendingCount == 0,
                "early cancellation lost accepted work");
        std::cout << "{\"kind\":\"correctness\",\"version\":\"" << (current ? "current" : "baseline")
                  << "\",\"workers\":" << workers << ",\"checks_total\":" << checks << "}\n";
    }

    template<class Graph>
    double timed(Scene<Graph>& scene, bool warm)
    {
        std::array<double, 19> times{};
        for (size_t index = 0; index < times.size() + 5; ++index)
        {
            scene.prepare(index != 0 && warm);
            const auto start = std::chrono::steady_clock::now();
            scene.publish();
            const double elapsed =
                std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - start).count();
            if (index >= 5)
            {
                times[index - 5] = elapsed;
            }
        }
        scene.check();
        std::sort(times.begin(), times.end());
        return times[times.size() / 2];
    }

    void benchmark(const char* name, size_t nodes, size_t passes, size_t usages, bool skew, bool warm)
    {
        observe = false;
        verifyContext = false;
        Scene<baseline::EnhancedRenderGraph> before(nodes, passes, usages, skew);
        Scene<current::EnhancedRenderGraph> after(nodes, passes, usages, skew);
        Scene<current::EnhancedRenderGraph> inlineScene(nodes, passes, usages, skew);
        const auto oldTime = timed(before, warm);
        const auto newTime = timed(after, warm);
        double inlineTime{};
        // Time inside the pool callback so its outer admission/join is excluded.
        // Production nested-worker fallback runs the identical materializer inline.
        ce::get_job_scheduler().submit([&] { inlineTime = timed(inlineScene, warm); }).wait();
        observe = true;
        reset_observer();
        after.prepare(warm);
        after.publish();
        after.check();
        size_t active{};
        for (size_t worker = 1; worker < workerRanges.size(); ++worker)
        {
            active += workerRanges[worker] != 0;
        }
        std::cout << "{\"kind\":\"fixture_timing\",\"case\":\"" << name << "\",\"baseline_median_us\":" << oldTime
                  << ",\"current_median_us\":" << newTime << ",\"jobs\":" << after.graph.m_declarationPacketJobs
                  << ",\"observed_workers\":" << active << ",\"forced_inline_median_us\":" << inlineTime
                  << ",\"worker_bytes\":[";
        for (size_t worker = 0; worker <= 8; ++worker)
        {
            std::cout << (worker ? "," : "") << workerBytes[worker].load();
        }
        std::cout << "],\"worker_ranges\":[";
        for (size_t worker = 0; worker <= 8; ++worker)
        {
            std::cout << (worker ? "," : "") << workerRanges[worker].load();
        }
        std::cout << "]}\n";
    }
} // namespace

int main(int argc, char** argv)
{
    try
    {
        thread_pool::worker_hooks hooks;
        hooks.on_start = [](uint32_t index) { workerIndex = (std::min)(size_t{16}, size_t{index}); };
        thread_pool::set_worker_hooks(hooks);
        ce::current_cpu_context = {73};
        auto& scheduler = ce::get_job_scheduler();
        for (const size_t workers : {size_t{1}, size_t{2}, size_t{4}, size_t{8}})
        {
            scheduler.start(workers);
            check_cases<baseline::EnhancedRenderGraph>(workers, false);
            check_cases<current::EnhancedRenderGraph>(workers, true);
            scheduler.shutdown();
        }
        verifyContext = true;
        Scene<current::EnhancedRenderGraph> stopped(8, 4, 8192, false);
        stopped.prepare();
        stopped.publish();
        stopped.check();
        require(stopped.graph.m_declarationPacketJobs == 1, "stopped scheduler did not fall back inline");
        scheduler.start(8);
        if (argc > 1 && std::string_view(argv[1]) == "--timing")
        {
            benchmark("warm_names", 37, 4, 0, false, true);
            benchmark("small_phases", 37, 4, 8, false, true);
            benchmark("medium_phases", 8, 8, 64, false, true);
            benchmark("medium_256_phases", 8, 8, 256, false, true);
            benchmark("medium_1024_phases", 8, 8, 1024, false, true);
            benchmark("medium_2048_phases", 8, 8, 2048, false, true);
            benchmark("skewed_phases", 8, 16, 8192, true, true);
        }
        scheduler.shutdown();
        std::cout << "{\"kind\":\"summary\",\"result\":\"PASS\",\"checks\":" << checks << "}\n";
    }
    catch (const std::exception& error)
    {
        blockBuilds = false;
        ce::get_job_scheduler().shutdown();
        std::cerr << "FAIL: " << error.what() << '\n';
        return 1;
    }
}
